using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

namespace AABattle {
 // 전투 중 사건 트리거 판정
 public static class RuntimeTriggers {
  public static IEnumerable<Potential> Field(Fighter fighter,Fighter opponent=null,TrainerRecord trainer=null,bool here=false){if(fighter==null||fighter.HP<=0)return Enumerable.Empty<Potential>();var active=TriggerStructures.Matching(fighter,TriggerStructures.AlwaysLabel).Concat(TriggerStructures.Matching(fighter,TriggerStructures.FieldLabel));if(here)active=active.Concat(TriggerStructures.Matching(fighter,TriggerStructures.HereLabel));active=active.Concat((fighter.Data.potentials??new Potential[0]).Where(p=>p!=null&&TriggerStructures.Clauses(p).Any(c=>{string granted;return TriggerStructures.TryGranted(c,out granted)&&HasGranted(fighter,granted);})));if(opponent!=null){active=active.Concat(AnsweredTriggers.Field(fighter,opponent,new Rules()));active=active.Concat((fighter.Data.potentials??new Potential[0]).Where(p=>p!=null&&TriggerStructures.Clauses(p).Any(c=>{string type;return TriggerStructures.TryOpponentType(c,out type)&&opponent.HP>0&&opponent.Data.types.Contains(type);})));}if(trainer!=null)active=active.Concat((fighter.Data.potentials??new Potential[0]).Where(p=>p!=null&&TriggerStructures.Clauses(p).Any(c=>TrainerCondition(c,trainer))));return active.Distinct();}
  static bool HasGranted(Fighter fighter,string name){return (fighter.Data.potentials??new Potential[0]).Any(p=>p!=null&&(p.name==name||p.name.StartsWith(name+" (")||p.name.StartsWith(name+"（")));}
  static bool TrainerCondition(string clause,TrainerRecord trainer){string aptitude,rank;if(!TriggerStructures.TryTrainerAptitude(clause,out aptitude,out rank))return false;AptitudeRecord value=aptitude=="지시"?trainer.command:aptitude=="육성"?trainer.training:aptitude=="통솔"?trainer.leadership:trainer.ability;return value!=null&&TriggerStructures.RankBand(value.rank,rank);}
  public static IEnumerable<string> Observers(IEnumerable<Fighter> reserves){return (reserves??Enumerable.Empty<Fighter>()).Where(f=>f.HP>0).SelectMany(f=>TriggerStructures.Matching(f,TriggerStructures.ObserverLabel).Select(p=>f.Data.name+" 『"+p.name+"』"));}
  public static void TurnEnd(Fighter[] fighters,Rules rules,Func<double> rng,Action<string> log){
   if(fighters==null)return;
   var order=Enumerable.Range(0,2).Where(i=>fighters[i]!=null&&fighters[i].HP>0).ToList();
   order.Sort((left,right)=>{int speedLeft=Engine.Effective(fighters[left],fighters[1-left],5,rules),speedRight=Engine.Effective(fighters[right],fighters[1-right],5,rules);if(speedLeft!=speedRight)return speedRight.CompareTo(speedLeft);return (rng??(()=>.5))()<.5?-1:1;});
   TimingEvents(order.Select(i=>fighters[i]),TriggerStructures.TurnEndLabel,log);
  }
  // 같은 타이밍의 포켓몬 효과는 「속도」 순(큐가 정렬), 트레이너 효과는 동시 처리
  public static void Timing(Fighter[] fighters,TrainerBattleState[] states,string label,Action<string> log){
   if(fighters==null)return;
   TimingEvents(fighters.Where(x=>x!=null&&x.OnField),label,log);
  }
  static void TimingEvents(IEnumerable<Fighter> owners,string label,Action<string> log){
   var fact=new TriggerFact{Kind="타이밍",Method=label};
   var list=owners.Where(x=>x!=null&&x.HP>0).ToList();
   var events=list.Select(x=>TriggerModules.EventFor(x,fact.For(true,false),x.Data.name+" · "+label,log)).Concat(list.Select(x=>{var state=BattleRecords.StateOf(x);return state==null?null:TrainerTriggers.EventFor(state.Trainer,fact.For(true,false),x,label,log);})).Where(x=>x!=null).ToArray();
   if(PotentialQueue.Active)foreach(var owner in list)BenchEvents.Dispatch(fact,owner,EffectScope.Current==null?null:EffectScope.Current.Opponent(owner),owner.Data.name+" · "+label,log);
   if(PotentialQueue.Active){if(events.Length>0)PotentialQueue.Raise(events);}else foreach(var e in events.Where(x=>x.Trainer==null))TriggerModules.LogPending(e);
  }
  public static bool Voluntary(SwitchReason reason){return reason!=SwitchReason.Forced;}
  public static bool Normal(SwitchReason reason){return reason==SwitchReason.Normal||reason==SwitchReason.Return;}
  static Fighter OpponentOf(Fighter f){var scope=EffectScope.Current;return scope==null?null:scope.Opponent(f);}
  public static void Leave(Fighter outgoing,SwitchReason reason,Action<string> log){if(outgoing==null)return;TriggerModules.Raise(new TriggerFact{Kind="퇴장",Method=reason==SwitchReason.Forced?"강제":"임의"},outgoing,OpponentOf(outgoing),outgoing.Data.name+" · "+TriggerStructures.LeaveLabel+" ["+reason+"]",log);}
  public static void Switch(Fighter outgoing,SwitchReason reason,Action<string> log){Switch(outgoing,null,reason,log);}
  // 교대(나가는 쪽): incoming은 교대해 나오는 아군(「「X」 타입 아군과 교대할 때」)
  public static void Switch(Fighter outgoing,Fighter incoming,SwitchReason reason,Action<string> log){if(outgoing==null)return;Leave(outgoing,reason,log);if(reason==SwitchReason.Fainted)return;TriggerModules.Raise(new TriggerFact{Kind="교대",Method=Voluntary(reason)?"임의":"강제",PartnerTypes=incoming==null?new string[0]:(incoming.Data.types??new string[0]).ToArray()},outgoing,OpponentOf(outgoing),outgoing.Data.name+" · 교대 ["+reason+"]",log);}
  // 「상대의 공격을 받았거나 무효화했을 때」(받았을 때는 Hit의 명중 사건이 맡는다)
  public static void Received(Fighter target,Fighter attacker,Move move,int bodyDamage,Action<string> log){if(target.HP<=0||bodyDamage<=0)return;string message=target.Data.name+"이 "+attacker.Data.name+"의 "+move.name+"으로 "+bodyDamage+" 대미지를 받았다.";if(TriggerStructures.Has(target,TriggerStructures.ReceivedOrNullifiedLabel))TriggerStructures.Fire(target,TriggerStructures.ReceivedOrNullifiedLabel,message,log);PriorityEffectRuntime.ActivateEvent(target,attacker,TriggerStructures.ReceivedLabel,message,log);}
  // 명중(타격마다): 공격한 쪽의 「명중했을 때」·「급소에 맞았을 때」와 받은 쪽의 「받았을 때」. 변화기술은 명중 판정을 통과했을 때
  public static void Hit(Fighter attacker,Fighter target,Move move,int bodyDamage,bool substitute,bool critical,double typeEffect,Action<string> log){
   if(attacker==null||target==null||move==null)return;
   var fact=new TriggerFact{Kind="명중",Move=move,User=attacker,Damaged=bodyDamage>0,Substitute=substitute,Critical=critical,TypeEffect=typeEffect,OtherAin=TriggerModules.IsAin(attacker),WasFull=AbilityEventRuntime.WasFull(target,attacker,bodyDamage)};
   TriggerModules.Raise(fact,attacker,target,attacker.Data.name+"의 "+move.name+"이 "+target.Data.name+"에게 명중했다."+(critical?" (급소)":""),log);
  }
  // 「기술을 내보냈을 때」(기술 처리 직후)
  public static void MoveUsed(Fighter user,Move move,Action<string> log){if(user==null||move==null)return;TriggerModules.Raise(new TriggerFact{Kind="기술 사용",Move=move,User=user,After=true},user,OpponentOf(user),user.Data.name+"이 "+move.name+"을 내보냈다.",log);}
  public static void Nullified(Fighter target,Fighter attacker,Move move,string reason,Action<string> log){if(target.HP>0&&Mechanics.DefensiveNullification(move,reason))TriggerModules.Raise(new TriggerFact{Kind="무효화",Move=move,User=attacker},target,attacker,target.Data.name+"이 "+move.name+"을 무효화했다",log);if(target.HP>0&&Mechanics.DefensiveNullification(move,reason)&&TriggerStructures.Has(target,TriggerStructures.ReceivedOrNullifiedLabel))TriggerStructures.Fire(target,TriggerStructures.ReceivedOrNullifiedLabel,target.Data.name+"이 "+attacker.Data.name+"의 "+move.name+"을 무효화했다. ["+reason+"]",log);if(target.HP>0&&Mechanics.DefensiveNullification(move,reason))PriorityEffectRuntime.ActivateEvent(target,attacker,TriggerStructures.ReceivedOrNullifiedLabel,target.Data.name+"이 "+attacker.Data.name+"의 "+move.name+"을 무효화했다. ["+reason+"]",log);}
  public static void DirectiveReceived(Fighter target,IEnumerable<Fighter> party,string order,Action<string> log){if(target!=null&&target.HP>0&&TriggerStructures.Has(target,TriggerStructures.SelfOrderLabel))TriggerStructures.Fire(target,TriggerStructures.SelfOrderLabel,target.Data.name+"이 『"+order+"』을 받았다.",log);foreach(var owner in (party??Enumerable.Empty<Fighter>()).Where(x=>x!=null&&x.HP>0&&TriggerStructures.Has(x,TriggerStructures.AllyOrderLabel)).Distinct())TriggerStructures.Fire(owner,TriggerStructures.AllyOrderLabel,"아군 "+target.Data.name+"이 『"+order+"』을 받았다.",log);}
  public static void Analyzed(Fighter analyst,IEnumerable<Fighter> party,Fighter target,Action<string> log){if(analyst!=null&&analyst.HP>0&&TriggerStructures.Has(analyst,TriggerStructures.AnalyzedLabel))TriggerStructures.Fire(analyst,TriggerStructures.AnalyzedLabel,analyst.Data.name+"이 "+target.Data.name+"의 데이터를 처음 해석했다.",log);}
  public static void BattleStart(TrainerRecord[] trainers,IEnumerable<Fighter>[] parties,Action<string> log){for(int side=0;side<2;side++){var trainer=trainers!=null&&side<trainers.Length?trainers[side]:null;TrainerTriggers.Fire(trainer,TriggerStructures.BattleStartLabel,(side+1)+"팀 배틀 시작",log);foreach(var owner in parties!=null&&side<parties.Length?parties[side]:Enumerable.Empty<Fighter>())if(owner!=null&&owner.HP>0&&TriggerStructures.Has(owner,TriggerStructures.BattleStartLabel))TriggerStructures.Fire(owner,TriggerStructures.BattleStartLabel,"배틀이 시작됐다.",log);}}
  public static void OpponentEntered(Fighter observer,Fighter entering,Action<string> log){OpponentEntered(observer,entering,null,log);}
  // 상대 등장 트리거는 EntryTriggers.Enter가 양쪽 관점으로 처리한다. 여기서는 우선도·선택 발동만
  public static void OpponentEntered(Fighter observer,Fighter entering,Rules rules,Action<string> log){if(observer!=null&&observer.HP>0&&entering!=null){PriorityEffectRuntime.ActivateEvent(observer,entering,TriggerStructures.OpponentEntryLabel,entering.Data.name+"이 장소에 나왔다.",log);OptionalEffectRuntime.Activate(observer,entering,TriggerStructures.OpponentEntryLabel,rules,log);}}
  // 「기술을 내보낼 때」(기술 직전)
  public static void BeforeMove(Fighter user,Move move,Action<string> log){if(user==null||user.HP<=0||move==null)return;TriggerModules.Raise(new TriggerFact{Kind="기술 사용",Move=move,User=user},user,OpponentOf(user),user.Data.name+"이 "+move.name+(move.extension?"(기능확장)":"")+"을 내보낸다.",log);}
  // 공격 성공의 우선도 효과(트리거는 Hit이 맡는다)
  public static void AttackSucceeded(Fighter user,Fighter target,Move move,Action<string> log){if(user!=null&&user.HP>0&&move!=null&&move.category!="변화")PriorityEffectRuntime.ActivateEvent(user,target,TriggerStructures.AttackSuccessLabel,user.Data.name+"의 "+move.name+" 공격이 "+target.Data.name+"에게 명중했다.",log);}
  public static void Damaged(Fighter target,int amount,string reason,Action<string> log){if(target!=null&&amount>0&&TriggerStructures.Has(target,TriggerStructures.DamagedLabel))TriggerStructures.Fire(target,TriggerStructures.DamagedLabel,target.Data.name+"이 "+reason+"로 "+amount+" 대미지를 받았다.",log);if(target!=null&&amount>0)PriorityEffectRuntime.ActivateEvent(target,null,TriggerStructures.DamagedLabel,target.Data.name+"이 "+reason+"로 "+amount+" 대미지를 받았다.",log);}
  public static bool HereThreshold(int initialSize,int living){return initialSize>=6?living<=3:initialSize>=4?living<=2:living<=1;}
  public static bool IsRole(Fighter fighter,params string[] names){return fighter!=null&&fighter.HP>0&&(fighter.Data.potentials??new Potential[0]).Any(p=>p!=null&&p.id=="역할"&&names.Contains(p.name));}
  public static bool HereNow(int initialSize,int living,Fighter opponent){return HereThreshold(initialSize,living)||IsRole(opponent,"에이스","탐사대장");}
  public static void Test(){
   var p=new Pokemon{name="관측자",level=100,@base=new[]{100,100,100,100,100,120},iv=new int[6],types=new[]{"노말"},moves=new string[0],potentials=new[]{new Potential{name="상시",description="공격이 오른다.",triggers=new[]{"필드에 있는 한"}},new Potential{name="관측",description="아군의 공격이 오른다.",triggers=new[]{"PT에 참가하고 있을 때"}},new Potential{name="종료",description="공격이 오른다.",triggers=new[]{"T종료시"}},new Potential{name="선회",description="공격이 오른다.",triggers=new[]{"아군과 교대할 때"}},new Potential{name="퇴장",description="공격이 오른다.",triggers=new[]{"필드를 떠날 때"}},new Potential{name="반격",description="공격이 오른다.",triggers=new[]{"상대의 공격을 받으면"}},new Potential{name="대화",description="공격이 오른다.",triggers=new[]{TriggerStructures.OpponentType("불꽃")}},new Potential{name="통솔",description="공격이 오른다.",triggers=new[]{TriggerStructures.TrainerAptitude("통솔","A")}},new Potential{name="방호",description="공격이 오른다.",triggers=new[]{TriggerStructures.ReceivedOrNullifiedLabel}}}};var fighter=new Fighter(p);if(Field(fighter).Count()!=1||Observers(new[]{fighter}).Count()!=1)throw new Exception("Continuous and observer triggers");var opponent=new Fighter(new Pokemon{name="불꽃",level=100,@base=new[]{100,100,100,100,100,100},iv=new int[6],types=new[]{"불꽃"},moves=new string[0]});var trainer=new TrainerRecord();trainer.leadership.rank="A+";if(Field(fighter,opponent,trainer).Count()!=3)throw new Exception("Type and trainer conditions");trainer.leadership.rank="AA";if(Field(fighter,opponent,trainer).Count()!=2)throw new Exception("Trainer rank band");fighter.HP=0;if(Field(fighter).Any()||Observers(new[]{fighter}).Any())throw new Exception("Fainted continuous trigger");fighter=new Fighter(p);int count=0;Switch(fighter,SwitchReason.Normal,x=>count++);if(count!=4)throw new Exception("Voluntary switch and leave triggers");count=0;Switch(fighter,SwitchReason.Forced,x=>count++);if(count!=0)throw new Exception("Forced switch exclusion");fighter.HP=0;Leave(fighter,SwitchReason.Fainted,x=>count++);if(count!=2)throw new Exception("Fainted leave trigger");var target=new Fighter(p);count=0;Received(target,fighter,new Move{name="연속공격"},3,x=>count++);Hit(fighter,target,new Move{name="연속공격",category="물리"},3,false,false,1,x=>count++);if(count!=4)throw new Exception("Received after move trigger");count=0;Nullified(target,fighter,new Move{name="공격",category="물리"},"타입 상성에 의한 무효",x=>count++);if(count!=2)throw new Exception("Defensive nullification trigger");count=0;Nullified(target,fighter,new Move{name="공격",category="물리"},"방어가 기술을 막았다",x=>count++);Received(target,fighter,new Move{name="연속공격"},0,x=>count++);target.HP=0;Received(target,fighter,new Move{name="연속공격"},3,x=>count++);if(count!=0)throw new Exception("Excluded nullification, no-damage or fainted received trigger");
  }
 }
}
